const _r=n=>Math.floor(Math.random()*n), _pick=a=>a[_r(a.length)];
const _shuf=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=_r(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;};
const faOmega=f=>f.d.length?f.c-f.d[f.d.length-1]:0;
const faDelta=f=>f.c+':'+f.d.length+(f.d.length?'Δ'+f.d.join(','):'');
const faOm=f=>f.c+':'+f.d.length+(f.d.length?' ω-'+faOmega(f):'');
const faN=f=>f.c+':'+f.d.length+(f.d.length?' n-'+faOmega(f):'');
const faKind=f=>!f.d.length?'กรดไขมันอิ่มตัว (SFA)':f.d.length===1?'กรดไขมันไม่อิ่มตัวเชิงเดี่ยว (MUFA)':'กรดไขมันไม่อิ่มตัวเชิงซ้อน (PUFA)';
/* สูตรโครงสร้างแบบย่อ */
function faCond(f){
  if(!f.d.length) return 'CH3(CH2)'+(f.c-2)+'COOH';
  const w=faOmega(f), last=f.d.length, tail=w-2, head=f.d[0]-2;
  const step=f.d.every((x,i)=>!i||x-f.d[i-1]===3);
  let mid;
  if(last===1) mid='CH=CH';
  else if(step) mid=(last===2?'CH=CHCH2':'(CH=CHCH2)'+(last-1))+'CH=CH';
  else mid=f.d.slice().reverse().map((x,i,a)=>'CH=CH'+(i<a.length-1?(a[i]-a[i+1]-2>0?'(CH2)'+(a[i]-a[i+1]-2):''):'')).join('');
  const t=tail===1?'CH3CH2':tail>1?'CH3(CH2)'+tail:'CH3';
  return (t+mid+(head>1?'(CH2)'+head:head===1?'CH2':'')+'COOH').replace(/\(CH2\)1(?!\d)/g,'CH2');
}
/* รูปโครงสร้างแบบเส้นซิกแซ็ก ปลาย COOH อยู่ขวา ปลาย methyl อยู่ซ้าย ไม่มีเลขกำกับ */
function faSVG(f,small){
  const n=f.c, dx=small?17:22, amp=small?8:11, padL=10, padR=small?46:58, H=small?50:66, W=padL+(n-1)*dx+padR, my=H/2+2;
  const P=[]; for(let i=1;i<=n;i++){ const k=n-i; P[i]={x:padL+k*dx, y:my+((i%2)?-amp:amp)}; }
  let s='';
  for(let i=1;i<n;i++){ const a=P[i], b=P[i+1]; s+=`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`;
    if(f.d.includes(i)){ const vx=b.x-a.x, vy=b.y-a.y, L=Math.hypot(vx,vy), ox=-vy/L*4.2, oy=vx/L*4.2, k=.16;
      const dir=oy>0?1:-1, fx=dir>0?ox:-ox, fy=dir>0?oy:-oy;
      s+=`<line x1="${(a.x+vx*k+fx).toFixed(1)}" y1="${(a.y+vy*k+fy).toFixed(1)}" x2="${(b.x-vx*k+fx).toFixed(1)}" y2="${(b.y-vy*k+fy).toFixed(1)}"/>`; } }
  const c1=P[1], fs=small?10:12.5;
  return `<svg class="fa" viewBox="0 0 ${W} ${H}" style="width:100%;max-width:${Math.round(W*(small?1:1.25))}px;height:auto" role="img" aria-label="โครงสร้างกรดไขมันแบบเส้น"><g fill="none" stroke="currentColor" stroke-width="${small?1.5:1.8}" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke">${s.replace(/<line /g,'<line vector-effect="non-scaling-stroke" ')}</g><text x="${c1.x+4}" y="${c1.y+fs*.36}" font-size="${fs}" font-weight="600" fill="currentColor" font-family="Inter,system-ui,sans-serif">COOH</text></svg>`;
}
const uniq=a=>a.filter((x,i)=>x&&a.indexOf(x)===i);
function mkQ(t,lv,stem,right,wrongs,exp,o){ wrongs=uniq(wrongs).filter(w=>w!==right); const opts=_shuf([right].concat(_shuf(wrongs).slice(0,3)));
  return Object.assign({t,lv,stem,opts,ans:opts.indexOf(right),exp:[].concat(exp)},o||{}); }
